// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Set;
import java.util.function.Supplier;

/** Test-only bridge to the packed search budget's clock, for planning that runs on the calling thread. */
public final class PackedPlanningDeadlineTestSupport {

	private PackedPlanningDeadlineTestSupport() {
	}

	/**
	 * Runs {@code planning} with every packed search budget created on this thread reaching its wall-clock deadline
	 * once {@code workUnits} search work units are charged; the clock then advances one nanosecond per further unit.
	 * Before that point the deadline lies in the future, whatever the real time. A budget's creation reads the real
	 * time, so the deadline keeps its real length and the overrun its real grace.
	 */
	public static <T> T withDeadlineAfterSearchWork(long workUnits, Supplier<T> planning) {
		Set<PackedSearchBudget> created = Collections.newSetFromMap(new IdentityHashMap<>());
		PackedSearchBudget.CLOCK_FOR_TESTS.set(budget -> created.add(budget) ? System.nanoTime()
				: budget.workUnits() >= workUnits
						? budget.deadlineNanos() + (budget.workUnits() - workUnits)
						: budget.deadlineNanos() - 1L);
		try {
			return planning.get();
		} finally {
			PackedSearchBudget.CLOCK_FOR_TESTS.remove();
		}
	}
}
